    @EventHandler( payloadType=UpdatePlacementEvent.class )
    public void handle( UpdatePlacementEvent event) {
    	LOGGER.info("handling UpdatePlacementEvent - " + event );
    	
	    Placement entity = new Placement();
            entity.setPlacementId( event.getPlacementId() );
            entity.setName( event.getName() );
            entity.setFlight( event.getFlight() );
            entity.setGoalImpressions( event.getGoalImpressions() );
            entity.setLineItem( event.getLineItem() );
            entity.setAdSlot( event.getAdSlot() );
            entity.setDeal( event.getDeal() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindPlacement( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllPlacement( entity );        
    }
    
