    /**
     * Method to retrieve the Placement via an PlacementPrimaryKey.
     * @param 	id Long
     * @return 	Placement
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Placement handle( FindPlacementQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getPlacementId() );
    }
    
    /**
     * Method to retrieve a collection of all Placements
     *
     * @param	query	FindAllPlacementQuery 
     * @return 	List<Placement> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Placement> handle( FindAllPlacementQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindPlacement,
 * but only if the id matches
 *
 * @param		entity	Placement
 */
	protected void emitFindPlacement( Placement entity ) {
		LOGGER.info("handling emitFindPlacement" );
		
	    queryUpdateEmitter.emit(FindPlacementQuery.class,
	                            query -> query.getFilter().getPlacementId().equals(entity.getPlacementId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllPlacement
	 * 
	 * @param		entity	Placement
	 */
	protected void emitFindAllPlacement( Placement entity ) {
		LOGGER.info("handling emitFindAllPlacement" );
		
	    queryUpdateEmitter.emit(FindAllPlacementQuery.class,
	                            query -> true,
	                            entity);
	}

